-- =====================================================================
-- Scheduled 3 of 4 · Export today's campaign list as CSV
-- Schedule: daily, about an hour after 02_score_daily.sql
-- Generated by `python -m appchurn.bqml`; edit config.py, not this file.
--
-- Writes High and Medium users outside the holdout to Cloud Storage, one
-- folder per score date, for a campaign platform to pick up. Stops with an
-- error if today's scores are missing, so a failed scoring run is never
-- followed by an empty or stale export.
--
-- Needs billing and a Cloud Storage bucket named your-bucket in the
-- same location as the dataset (US).
-- =====================================================================

DECLARE run_date DATE DEFAULT DATE '2018-10-04';  -- when scheduling, use: DEFAULT @run_date
DECLARE rows_to_export INT64;

SET rows_to_export = (
  SELECT COUNT(*) FROM `your-project-id.churn_demo.at_risk_customers`
  WHERE score_date = run_date AND risk_band IN ('High', 'Medium') AND NOT in_holdout
);
IF rows_to_export = 0 THEN
  RAISE USING MESSAGE = FORMAT('No scores for %t: run 02_score_daily.sql first', run_date);
END IF;

EXECUTE IMMEDIATE REPLACE(r"""
EXPORT DATA OPTIONS (
  uri = 'gs://your-bucket/churn/at_risk/score_date=__DATE__/*.csv',
  format = 'CSV',
  header = true,
  overwrite = true
) AS
SELECT score_date, risk_rank, user_pseudo_id, risk_band, churn_probability, reasons
FROM `your-project-id.churn_demo.at_risk_customers`
-- Production: join the identity map (app user -> customer ID) and filter on
-- marketing consent and contact caps here, before anything leaves the warehouse.
WHERE score_date = DATE '__DATE__'
  AND risk_band IN ('High', 'Medium')
  AND NOT in_holdout
ORDER BY risk_rank
""",
  '__DATE__', CAST(run_date AS STRING));

SELECT rows_to_export AS exported_rows;
